def declares_transfer_pair(provider) -> bool:
    """Whether a provider declares the direct-migration ``transfer_*`` pair.

    Only a provider whose ``capabilities["operations"]`` lists BOTH
    ``transfer_out`` and ``transfer_in`` takes the direct ciphertext-transfer
    migrate path (contract validation guarantees both are callables); the
    built-in local provider always declares and implements the pair. Anything
    else -- including exactly one of the two, which never survives contract
    validation -- keeps the export/import migrate path.
    """
    caps = getattr(provider, "capabilities", None)
    if not isinstance(caps, dict):
        return False
    operations = caps.get("operations")
    if not isinstance(operations, (list, tuple)):
        return False
    return OP_TRANSFER_OUT in operations and OP_TRANSFER_IN in operations


# -- direct migration transfer blob -----------------------------------------
# Both built-in/cooperating providers seal the material handed across a
# direct migrate with the SAME wire format, so e.g. the built-in local
# provider and a module:factory peer that adopts this encoding can transfer
# between each other. The blob is never persisted: it exists only in memory
# between ``transfer_out`` and ``transfer_in``; it is an opaque token to the
# service layer. Chain peers are all configured with the same data directory,
# so a 0600 per-deployment transport key in it lets the two PROVIDER backends
# seal/open the blob while the service itself never can (store.py never calls
# these helpers and never sees the raw material).
_TRANSFER_PREFIX = b"kmt1."
_TRANSFER_KEY_NAME = "transfer.key"
_TRANSFER_AAD_PREFIX = b"keymgr-transfer-v1\0"


def _transfer_key(data_dir: str) -> bytes:
    """Load (or create) the 0600 per-deployment transfer transport key."""
    path = os.path.join(data_dir, _TRANSFER_KEY_NAME)
    try:
        with open(path, "rb") as fh:
            key = fh.read()
        if len(key) == _DEK_LEN:
            return key
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise ProviderUnavailable("cannot read transfer key: %s" % exc) from exc
    key = os.urandom(_DEK_LEN)
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            os.write(fd, key)
            os.fsync(fd)
        finally:
            os.close(fd)
    except FileExistsError:
        with open(path, "rb") as fh:
            key = fh.read()
    except OSError as exc:
        raise ProviderUnavailable("cannot write transfer key: %s" % exc) from exc
    if len(key) != _DEK_LEN:
        raise ProviderUnavailable("transfer key file is corrupt")
    return key


def _transfer_aad(
    source_provider_id: str, target_provider_id: str, algorithm: str
) -> bytes:
    return (
        _TRANSFER_AAD_PREFIX
        + source_provider_id.encode("utf-8")
        + b"\0"
        + target_provider_id.encode("utf-8")
        + b"\0"
        + algorithm.encode("utf-8")
    )


def _transfer_seal(
    data_dir: str,
    source_provider_id: str,
    target_provider_id: str,
    algorithm: str,
    public_key,
    raw_material: str,
) -> bytes:
    """Seal one key's raw material for a named migration peer (provider side).

    The payload (algorithm, public component, raw material) is sealed with
    AES-256-GCM under the per-deployment transport key and AAD that binds BOTH
    endpoint provider ids and the algorithm, so a blob cannot be redirected or
    tampered with. Only another provider configured for the same data dir can
    open it; the service layer treats the result as opaque bytes.
    """
    if not isinstance(raw_material, str) or not raw_material:
        raise ProviderUnavailable("cannot transfer empty material")
    nonce = os.urandom(_NONCE_LEN)
    payload = json.dumps(
        {
            "public_key": public_key,
            "material": raw_material,
        },
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")
    aad = _transfer_aad(source_provider_id, target_provider_id, algorithm)
    ciphertext = AESGCM(_transfer_key(data_dir)).encrypt(nonce, payload, aad)
    envelope = json.dumps(
        {
            "v": 1,
            "s": source_provider_id,
            "t": target_provider_id,
            "a": algorithm,
            "n": _b64e(nonce),
            "c": _b64e(ciphertext),
        },
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")
    return _TRANSFER_PREFIX + base64.b64encode(envelope)


def _transfer_open(
    data_dir: str,
    blob: bytes,
    source_provider_id: str,
    target_provider_id: str,
):
    """Open a transfer blob INSIDE the target provider, returning raw facts.

    Returns ``(algorithm, public_key, raw_material)``. Structural tampering,
    an AAD/endpoint mismatch or any failed authentication raises
    :class:`ProviderInvalidMaterial`; an unsupported embedded algorithm also
    raises :class:`ProviderInvalidMaterial` (the migrate path surfaces every
    such failure as the fixed 503, never a field-level 400).
    """
    if not isinstance(blob, bytes) or not blob:
        raise ProviderInvalidMaterial("malformed transfer blob")
    if not blob.startswith(_TRANSFER_PREFIX):
        raise ProviderInvalidMaterial("unrecognized transfer blob")
    try:
        envelope = json.loads(base64.b64decode(blob[len(_TRANSFER_PREFIX):]))
        nonce = _b64d(envelope["n"])
        ciphertext = _b64d(envelope["c"])
        algorithm = envelope["a"]
        blob_source = envelope["s"]
        blob_target = envelope["t"]
    except (ValueError, KeyError, TypeError) as exc:
        raise ProviderInvalidMaterial("malformed transfer blob") from exc
    if (
        blob_source != source_provider_id
        or blob_target != target_provider_id
        or algorithm not in SUPPORTED_ALGORITHMS
        or len(nonce) != _NONCE_LEN
        or not ciphertext
    ):
        raise ProviderInvalidMaterial("transfer blob does not authenticate")
    aad = _transfer_aad(source_provider_id, target_provider_id, algorithm)
    try:
        payload = json.loads(
            AESGCM(_transfer_key(data_dir)).decrypt(nonce, ciphertext, aad)
        )
    except InvalidTag as exc:
        raise ProviderInvalidMaterial(
            "transfer blob does not authenticate"
        ) from exc
    except ValueError as exc:
        raise ProviderInvalidMaterial("malformed transfer blob") from exc
    if not isinstance(payload, dict):
        raise ProviderInvalidMaterial("malformed transfer blob")
    public_key = payload.get("public_key")
    raw_material = payload.get("material")
    if not isinstance(raw_material, str) or not raw_material:
        raise ProviderInvalidMaterial("malformed transfer blob")
    if public_key is not None and (
        not isinstance(public_key, str) or not public_key
    ):
        raise ProviderInvalidMaterial("malformed transfer blob")
    return algorithm, public_key, raw_material


class LocalProvider(KeyProvider):
    """Built-in software provider.

    Raw material never lands in a key file: each generated/imported key is
    wrapped with AES-256-GCM under a data-encryption key kept in
    ``local.dek`` (0600), and only the wrapped blob plus an opaque handle is
    persisted. A small registry (``local-registry.json``, 0600) maps each
    handle to its algorithm and wrapped blob, so ``export_material(handle)``
    can re-derive the raw material and ``delete`` stays idempotent. The
    registry stores only DEK-wrapped material, never plaintext.
    """

    provider_id = LOCAL_PROVIDER_ID
    capabilities = {
        "algorithms": tuple(SUPPORTED_ALGORITHMS),
        # The local provider declares and implements the optional native
        # ``sign``, ``unwrap_key``, ``wrap_key`` and ``rewrap_key``
        # operations: signing and native DEK wrapping/unwrapping/rewrapping
        # happen inside the provider and the unwrapped private key never
        # crosses the boundary. It also declares the ``transfer_out``/
        # ``transfer_in`` pair used by whole-key migration between two chain
        # entries, so a migrate whose source and ready provider both support
        # the pair moves an opaque sealed blob rather than exporting raw
        # material into the service.
        "operations": OPERATIONS + (
            OP_SIGN,
            OP_UNWRAP_KEY,
            OP_WRAP_KEY,
            OP_REWRAP_KEY,
            OP_TRANSFER_OUT,
            OP_TRANSFER_IN,
        ),
    }

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._data_dir: Optional[str] = None
        self._dek: Optional[bytes] = None
        self._registry: dict = {}
        self._configured = False

    # -- state -------------------------------------------------------------
    def configure(self, data_dir: str) -> None:
        with self._lock:
            if self._configured and self._data_dir == data_dir:
                return
            os.makedirs(data_dir, exist_ok=True)
            self._data_dir = data_dir
            self._dek = self._load_or_create_dek(data_dir)
            self._registry = self._load_registry(data_dir)
            self._configured = True

    @staticmethod
    def _load_or_create_dek(data_dir: str) -> bytes:
        path = os.path.join(data_dir, _DEK_NAME)
        try:
            with open(path, "rb") as fh:
                dek = fh.read()
            if len(dek) == 32:
                return dek
        except FileNotFoundError:
            pass
        except OSError as exc:
            raise ProviderUnavailable("cannot read local DEK: %s" % exc) from exc
        dek = os.urandom(32)
        try:
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            try:
                os.write(fd, dek)
                os.fsync(fd)
            finally:
                os.close(fd)
        except FileExistsError:
            with open(path, "rb") as fh:
                dek = fh.read()
        except OSError as exc:
            raise ProviderUnavailable("cannot write local DEK: %s" % exc) from exc
        if len(dek) != 32:
            raise ProviderUnavailable("local DEK file is corrupt")
        return dek

    @staticmethod
    def _load_registry(data_dir: str) -> dict:
        path = os.path.join(data_dir, _REGISTRY_NAME)
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except FileNotFoundError:
            return {}
        except (OSError, ValueError) as exc:
            raise ProviderUnavailable(
                "cannot read local handle registry: %s" % exc
            ) from exc
        if not isinstance(data, dict):
            raise ProviderUnavailable("local handle registry is corrupt")
        return data

    def _persist_registry_locked(self) -> None:
        path = os.path.join(self._data_dir, _REGISTRY_NAME)
        fd, tmp_path = tempfile.mkstemp(dir=self._data_dir, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(self._registry, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _require_configured(self) -> None:
        if not self._configured:
            raise ProviderUnavailable("local provider is not configured")

    # -- wrapping ----------------------------------------------------------
    def _wrap_locked(self, raw_material: str) -> str:
        nonce = os.urandom(_NONCE_LEN)
        ct = AESGCM(self._dek).encrypt(
            nonce, raw_material.encode("utf-8"), None
        )
        return _WRAP_PREFIX + _b64e(nonce) + "." + _b64e(ct)

    def _unwrap_locked(self, blob: str) -> str:
        if not isinstance(blob, str) or not blob.startswith(_WRAP_PREFIX):
            raise ProviderUnavailable("stored material is not a local blob")
        try:
            nonce_b, ct_b = blob[len(_WRAP_PREFIX):].split(".", 1)
            nonce = _b64d(nonce_b)
            ct = _b64d(ct_b)
            raw = AESGCM(self._dek).decrypt(nonce, ct, None)
            return raw.decode("utf-8")
        except Exception as exc:
            raise ProviderUnavailable(
                "cannot unwrap local material"
            ) from exc

    # -- material validation ----------------------------------------------
    @staticmethod
    def _validate_material(
        algorithm: str, public_key, material
    ):
        """Validate raw (legacy-shaped) material for an algorithm.

        AES material is base64 of exactly 32 bytes and has no public part;
        RSA material is a PEM private key of exactly 2048 bits, and the
        supplied public key (when present) must match it. Returns the parsed
        RSA private key (None for AES).
        """
        if not isinstance(material, str) or not material:
            raise ProviderInvalidMaterial(
                "field encrypted_material must be a non-empty string"
            )
        if algorithm == "AES256":
            if public_key is not None:
                raise ProviderInvalidMaterial(
                    "field public_key must be null for AES256"
                )
            try:
                raw = base64.b64decode(material, validate=True)
            except (ValueError, TypeError) as exc:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be valid base64 for AES256"
                ) from exc
            if len(raw) != 32:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must decode to 32 bytes for AES256"
                )
            return None
        if algorithm == "RSA2048":
            try:
                private_key = serialization.load_pem_private_key(
                    material.encode("utf-8"), password=None
                )
            except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be a PEM private key for RSA2048"
                ) from exc
            if not isinstance(private_key, rsa.RSAPrivateKey) or (
                private_key.key_size != 2048
            ):
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be a 2048-bit RSA private key"
                )
            if public_key is not None:
                if not isinstance(public_key, str) or not public_key:
                    raise ProviderInvalidMaterial(
                        "field public_key must be a PEM string for RSA2048"
                    )
                try:
                    supplied = serialization.load_pem_public_key(
                        public_key.encode("utf-8")
                    )
                    if not isinstance(supplied, rsa.RSAPublicKey):
                        raise ValueError("not an RSA public key")
                except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
                    raise ProviderInvalidMaterial(
                        "field public_key must be a PEM RSA public key"
                    ) from exc
                expected = private_key.public_key().public_bytes(
                    encoding=serialization.Encoding.DER,
                    format=serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                actual = supplied.public_bytes(
                    encoding=serialization.Encoding.DER,
                    format=serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                if expected != actual:
                    raise ProviderInvalidMaterial(
                        "field public_key does not match the private key"
                    )
            return private_key
        raise ProviderInvalidMaterial(
            "unsupported value for field algorithm: %r (supported: %s)"
            % (algorithm, ", ".join(SUPPORTED_ALGORITHMS))
        )

    @staticmethod
    def _public_pem(private_key) -> str:
        return private_key.public_key().public_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PublicFormat.SubjectPublicKeyInfo,
        ).decode("ascii")

    def _adopt(
        self,
        algorithm: str,
        public_key,
        raw_material: str,
    ) -> MaterialTriple:
        """Validate raw material, wrap it under the DEK, mint a handle."""
        self._require_configured()
        private_key = self._validate_material(algorithm, public_key, raw_material)
        if algorithm == "RSA2048" and public_key is None:
            public_key = self._public_pem(private_key)
